INSERT INTO textile_designer_profile (user_id, designer_no, name, gender, birth_date, phone, email, education, major, certificate, specialty, experience_years, introduction, work_experience, achievements, skill_tags, rating, good_rate, total_projects, total_awards, status) VALUES
(1001, 'TEX001', '张伟', 1, '1985-03-15', '13800138001', 'zhangwei@example.com', '硕士', '纺织材料与纺织品设计', '高级纺织面料设计师职业资格证,中国国际面料设计大赛获奖者', '面料设计', 12, '资深面料设计师，专注功能性与生态面料开发 12 年，主导多款量产面料的成分设计与织造工艺落地。', '2014-2018年 在某纺织研究院担任主任面料设计师\n2018-至今 在本机构担任面料设计总监', '2020年获得中国国际面料设计大赛金奖\n2022年主导的凉感功能面料实现量产', '面料设计,织造工艺,功能整理,纱线选型,试纺打样', 4.8, 96.50, 25, 6, 1),
(1002, 'TEX002', '李芳', 0, '1990-07-22', '13800138002', 'lifang@example.com', '本科', '家用纺织品设计', '中级家用纺织品设计师职业资格证,中国国际家用纺织品设计大赛获奖者', '家纺设计', 8, '家纺设计师，擅长床品与窗帘的图案配套设计与印染提花工艺落地，熟悉棉麻、天丝与遮光涂层工艺。', '2016-2019年 在某家纺品牌担任产品设计师\n2019-至今 在本机构担任资深设计师', '2021年设计的模块化床品套件获中国国际家用纺织品设计大赛金奖\n2023年主导的适老化家纺系列实现量产', '家纺设计,图案配套,提花工艺,遮光涂层,印染工艺', 4.9, 98.20, 30, 8, 1),
(1003, 'TEX003', '王强', 1, '1988-11-08', '13800138003', 'wangqiang@example.com', '硕士', '服装设计与工程', '高级服装设计师职业资格证,服装制版师专项认证', '服装设计', 11, '服装设计师，参与过多品牌四季系列的款式与版型开发，擅长立体裁剪与版型修正把控。', '2012-2015年 在某服装品牌设计中心任职\n2015-至今 在本机构担任设计经理', '2018年参与系列获中国时装设计优秀奖\n2021年获得中国国际青年设计师大赛年度概念系列奖', '服装设计,立裁制版,系列开发,面料应用,缝制工艺', 4.7, 95.80, 22, 5, 1),
(1004, 'TEX004', '赵敏', 0, '1992-05-30', '13800138004', 'zhaomin@example.com', '本科', '染整工程', '纺织品检测工程师认证,染色工技师证', '印染工艺', 6, '印染工艺师，熟悉活性/分散染料染色工艺与数码印花流程，主导过多款面料的染整工艺落地与缸差控制。', '2018-2020年 在某染整企业担任工艺员\n2020-至今 在本机构任职', '2021年主导的数码印花工艺通过 Oeko-Tex 认证\n2023年获得省级印染行业技术创新奖', '印染工艺,数码印花,活性染料,缸差控制,色牢度', 4.6, 94.30, 18, 3, 1),
(1005, 'TEX005', '刘伟', 1, '1983-09-12', '13800138005', 'liuwei@example.com', '博士', '纺织工程', '教授级高级工程师,中国纺织工程学会会员', '针织工艺', 15, '针织工艺与面料开发专家，精通经编/纬编织物组织设计、圆机与横机工艺参数及功能性针织面料开发。', '2009-2013年 在某针织集团担任工艺主管\n2013-至今 在本机构担任首席面料工程师', '2016年获得中国纺织工业联合会科技进步奖\n2020年主导的导湿快干针织面料获中国国际面料设计大赛金奖', '针织工艺,经编纬编,织物组织,功能面料,工艺参数', 4.9, 97.60, 40, 10, 1),
(1006, 'TEX006', '陈静', 0, '1995-01-18', '13800138006', 'chenjing@example.com', '本科', '纺织品艺术设计', '纺织品图案设计师认证,色彩搭配师认证', '花型设计', 5, '纺织品图案设计师，擅长印花图案创意、配色循环与数码印花分色，熟悉潘通色卡与印花回位对花。', '2019-至今 在本机构任职', '2021年主导的印花图案系列获省级设计奖\n2023年完成某家纺品牌全年花型开发', '花型设计,图案创意,配色循环,数码印花,分色制版', 4.5, 93.50, 15, 2, 1),
(1007, 'TEX007', '孙涛', 1, '1987-06-25', '13800138007', 'suntao@example.com', '硕士', '纺织材料与纺织品设计', '纺织面料工程师执业资格,功能纺织品检测认证', '纺织材料', 9, '纺织材料工程师，专注新型纤维（莱赛尔、原液着色、再生涤纶）应用与混纺面料开发，累计参与 30 余款量产面料落地。', '2015-2018年 在某化纤企业任职\n2018-至今 在本机构担任材料负责人', '2019年主导的再生涤纶混纺方案降低成本 18%\n2022年获得集团技术创新奖', '纺织材料,新型纤维,混纺设计,纱线选型,物性测试', 4.7, 95.20, 28, 4, 1),
(1008, 'TEX008', '周丽', 0, '1991-12-03', '13800138008', 'zhouli@example.com', '本科', '服装设计与工程', '色彩管理师认证,印染工艺应用认证', '色彩管理', 7, '色彩管理师，负责潘通色号转换、染色配方管理与色差（ΔE）控制，熟悉 lab dip 对色与不同光源评级。', '2017-至今 在本机构任职', '2020年建立的品牌色卡管理体系被集团推广采用\n2022年获得中国纺织面料色彩管理专项奖', '色彩管理,潘通色号,染色配方,色差控制,对色评级', 4.8, 96.80, 32, 6, 1),
(1009, 'TEX009', '吴刚', 1, '1986-04-10', '13800138009', 'wugang@example.com', '硕士', '非织造材料与工程', '产业用纺织品工程师认证,过滤材料检测认证', '产业用纺织品', 11, '产业用纺织品设计师，擅长非织造布与功能性过滤、医用防护材料的结构设计与工艺开发。', '2013-2016年 在某产业用纺织品企业任职\n2016-至今 在本机构担任技术总监', '2018年主导某品牌医用防护材料结构升级\n2021年出版《产业用非织造布开发实践》', '非织造布,产业用纺织品,过滤材料,防护材料,结构设计', 4.6, 94.70, 22, 4, 1),
(1010, 'TEX010', '郑雪', 0, '1993-08-28', '13800138010', 'zhengxue@example.com', '本科', '纺织工程', 'GRS 全球回收标准审核员认证,可持续纺织认证', '可持续纺织', 6, '可持续纺织设计师，专注再生纤维应用、无水染色工艺与纺织品循环利用方案。', '2018-2020年 在某环保材料企业任职\n2020-至今 在本机构任职', '2021年主导的再生涤纶系列实现 65% 再生材料占比\n2023年获得绿色纺织贡献奖', '可持续纺织,再生纤维,GRS认证,无水染色,循环利用', 4.7, 95.50, 18, 3, 1);
INSERT INTO textile_design_project (designer_id, project_name, project_code, stage, design_cycle, milestone_count, start_date, end_date, design_objectives, design_content, design_methods, acceptance_criteria, schedule_details, project_status, review_comment, actual_progress, design_effect) VALUES
(1, '凉感功能面料开发', 'TEX-FABRIC-001', '面料开发', 60, 5, '2024-03-01', '2024-04-30', '开发适用于夏季服装的凉感功能面料，满足接触凉感与耐洗性要求', '纤维选型（凉感涤纶/锦纶）与纱线结构设计\n织物组织设计（平纹/提花）与密度优化\n功能整理（凉感助剂/吸湿速干）工艺验证', '纱线选型,小样试织,功能整理,物性测试', '接触凉感系数 Q-max 不低于 0.15；20 次水洗后凉感保持率不低于 80%；克重 150g/m²±5%', '{"week1-2": "纤维选型与纱线设计", "week3-5": "小样试织与组织优化", "week6-8": "功能整理与大货验证"}', 4, '凉感性能达标，耐洗稳定性需进一步验证', 75.00, '良好'),
(1, '再生涤纶混纺衬衫面料', 'TEX-FABRIC-002', '详细设计', 75, 6, '2024-05-01', '2024-07-15', '在成本约束下完成再生涤纶与棉的混纺面料设计，兼顾手感与强度', '混纺比设计（再生涤纶/棉 65/35）\n纱线捻度与织造密度优化\n染整工艺与手感整理验证', '混纺设计,小样试织,染整验证', '撕破强力不低于 12N；水洗尺寸变化率经向不大于 3%、纬向不大于 2%；再生材料占比不低于 65%', '{"week1-2": "混纺比设计", "week3-6": "小样试织与密度优化", "week7-10": "染整验证与大货样"}', 4, '手感良好，建议进一步优化染整降强问题', 60.00, '良好'),
(2, '模块化床品套件设计', 'TEX-BEDDING-001', '样机验证', 45, 4, '2024-02-15', '2024-04-01', '设计可自由组合的模块化床品套件，兼顾图案配套与拆装便利性', '模块单元尺寸与配套关系规划\n被套/床单/枕套图案循环与对花设计\n棉麻材质与印染工艺选型', '图案配套,实物打样,印染验证', '印花循环对花偏差不超过 2mm；水洗 10 次后变色不低于 4 级；用户可在 10 分钟内完成单模块更换', '{"week1": "模块尺寸规划", "week2-3": "图案配套设计", "week4-6": "印染打样与测试"}', 5, '图案配套完整，拆装体验良好', 100.00, '优秀'),
(2, '适老化家纺系列设计', 'TEX-HOME-002', '方案设计', 50, 5, '2024-06-01', '2024-07-20', '面向老年用户的家纺系列，重点解决高对比度识别与防滑安全问题', '老年用户访谈与卧室场景分析\n高对比度图案与色彩警示设计\n防滑床垫保护套结构与材质', '用户访谈,场景测试,印染打样', '图案对比度满足无障碍识别要求；防滑底布静摩擦系数大于 0.6', '{"week1-2": "用户研究与场景分析", "week3-5": "图案与结构方案", "week6-7": "样机验证"}', 4, '无障碍考虑充分，防滑方案需补充湿态测试', 55.00, '良好'),
(3, '品牌四季系列服装开发', 'TEX-GARMENT-001', '概念提案', 90, 6, '2024-01-10', '2024-04-10', '定义下一季系列的廓形语言与面料应用方向', '流行趋势研究与系列关键词定义\n廓形比例与款式草图\n面料小样与立裁验证', '趋势研究,草图发散,立裁验证', '系列款式通过品牌方两轮评审；核心面料通过撕破与色牢度测试', '{"week1-3": "趋势研究与关键词", "week4-8": "廓形与款式草图", "week9-12": "立裁与样衣评审"}', 4, '廓形系列完整，面料应用需进一步明确', 45.00, '良好'),
(5, '导湿快干针织面料开发', 'TEX-KNIT-001', '详细设计', 120, 8, '2023-10-01', '2024-01-31', '完成运动内衣用导湿快干针织面料的组织设计与功能整理', '异形截面纤维选型与纱线结构\n经编/纬编组织对比与参数优化\n吸湿速干整理与芯吸高度验证', '功能纤维应用,针织工艺,物性测试', '芯吸高度不低于 100mm；蒸发速率不低于 0.2g/h；50 次水洗后功能保持率不低于 85%', '{"week1-4": "纤维与纱线选型", "week5-10": "组织设计与工艺优化", "week11-17": "整理验证与样布"}', 5, '功能指标全部达标，具备大货条件', 100.00, '优秀'),
(7, '再生涤纶混纺工艺优化', 'TEX-BLEND-001', '详细设计', 40, 4, '2024-04-01', '2024-05-10', '优化混纺面料染整工艺，控制染后强力损失', '染色温度与 pH 工艺曲线优化\n固色剂与柔软剂选型\n染后强力与手感平衡测试', '染整工艺优化,强力测试,手感评级', '染后撕破强力保持率不低于 90%；弯曲长度不大于 2.5cm；单米染费下降 10%', '{"week1-2": "工艺曲线优化", "week3-4": "助剂选型", "week5-6": "大货验证"}', 4, '染整数据充分，建议补充批量稳定性验证', 70.00, '良好'),
(8, '家纺品牌色卡体系建设', 'TEX-COLOR-001', '方案设计', 60, 5, '2024-03-15', '2024-05-15', '建立覆盖三大产品线的标准色卡与对色规范', '流行色研究与本季主色定义\n潘通色号转换与染色配方管理\n标准色卡制作与编号规则', '色彩管理,染色配方,色卡打样', '同缸色差 ΔE 不大于 1.0；缸差 ΔE 不大于 1.5；色卡通过 500 小时耐光照测试', '{"week1-3": "趋势与色彩定义", "week4-6": "色号转换与配方", "week7-9": "标准色卡制作"}', 4, '色彩体系完整，建议补充不同批次色差管控说明', 65.00, '良好'),
(10, '可循环再生家纺系列设计', 'TEX-ECO-001', '样机验证', 55, 5, '2024-05-20', '2024-07-15', '以循环利用为目标设计的免工具拆洗再生纤维家纺系列', '再生纤维选型（GRS 认证涤纶）\n单一材质设计与可拆洗结构\n回收路径与认证资料验证', '再生纤维应用,结构设计,GRS认证', '再生材料占比不低于 65%；免工具拆洗时间小于 3 分钟；通过 GRS 认证审核', '{"week1-2": "再生纤维选型", "week3-5": "结构与材质", "week6-8": "认证与回收验证"}', 5, '回收路径清晰，材料单一化程度高', 100.00, '优秀');
INSERT INTO textile_design_review (designer_id, reviewer_id, project_id, project_name, overall_score, innovation_score, usability_score, professional_score, interaction_score, processability_score, review_content, sentiment_type, sentiment_score, is_anonymous) VALUES
(1, 2001, 1, '凉感功能面料开发', 5.0, 5.0, 5.0, 5.0, 5.0, 5.0, '纤维选型与凉感助剂方案搭配合理，试纺数据充分，物性指标全部达标，评审一次通过。', 'positive', 0.95, 0),
(1, 2002, 1, '凉感功能面料开发', 4.5, 5.0, 4.5, 5.0, 4.0, 4.5, '创新性突出，但20次水洗后的凉感保持率建议补充更严格的验证。', 'positive', 0.82, 0),
(1, 2003, 2, '再生涤纶混纺衬衫面料', 4.5, 4.5, 4.5, 5.0, 4.5, 4.0, '混纺比设计合理，但染后强力损失偏大，建议优化染色温度曲线。', 'positive', 0.78, 0),
(2, 2004, 3, '模块化床品套件设计', 5.0, 4.5, 5.0, 5.0, 5.0, 5.0, '模块组合自由度很高，图案循环对花精准，用户拆装体验优秀。', 'positive', 0.94, 0),
(2, 2005, 3, '模块化床品套件设计', 4.5, 4.5, 5.0, 4.5, 4.5, 4.5, '印花色牢度达标，建议补充说明不同湿度环境下的对花稳定性控制措施。', 'positive', 0.86, 0),
(2, 2006, 4, '适老化家纺系列设计', 4.5, 4.0, 5.0, 4.5, 4.5, 4.0, '高对比度图案的人机数据很扎实，防滑方案建议补充湿态地面测试。', 'positive', 0.80, 0),
(3, 2007, 5, '品牌四季系列服装开发', 4.5, 5.0, 4.0, 5.0, 4.5, 4.0, '廓形系列完整，比例舒展，但核心面料方向不够明确，建议尽早锁定。', 'positive', 0.83, 0),
(3, 2008, 5, '品牌四季系列服装开发', 4.0, 4.5, 4.0, 4.5, 4.0, 3.5, '概念方向可行，面料的撕破强力数据还需第三方检测复核后再进入下一阶段。', 'neutral', 0.55, 0),
(5, 2009, 6, '导湿快干针织面料开发', 5.0, 4.5, 5.0, 5.0, 5.0, 5.0, '异形纤维选型与组织设计到位，芯吸高度与蒸发速率全部达标，达到大货标准。', 'positive', 0.97, 0),
(5, 2010, 6, '导湿快干针织面料开发', 5.0, 5.0, 5.0, 5.0, 4.5, 5.0, '工艺参数合理，维护打样便利，是本年度标杆项目。', 'positive', 0.93, 0),
(7, 2011, 7, '再生涤纶混纺工艺优化', 4.5, 4.0, 4.5, 5.0, 4.5, 5.0, '工艺曲线优化充分，强力保持率控制到位，建议补充批量生产的稳定性验证。', 'positive', 0.88, 0),
(7, 2012, 7, '再生涤纶混纺工艺优化', 4.0, 4.0, 4.0, 4.5, 4.0, 4.5, '大货样手感良好，但个别批次仍存在轻微色花，需微调匀染方案。', 'neutral', 0.62, 0),
(8, 2013, 8, '家纺品牌色卡体系建设', 4.5, 4.5, 4.5, 5.0, 4.5, 4.5, '色彩体系完整，色卡制作精细，建议补充不同批次间的缸差管控说明。', 'positive', 0.89, 0),
(8, 2014, 8, '家纺品牌色卡体系建设', 5.0, 5.0, 5.0, 5.0, 5.0, 4.5, '色卡体系可直接用于染厂交付，大幅降低沟通成本。', 'positive', 0.95, 0),
(10, 2015, 9, '可循环再生家纺系列设计', 5.0, 5.0, 5.0, 4.5, 5.0, 4.5, '回收路径清晰，材料单一化程度高，GRS 认证资料完整，是可持续纺织的优秀范例。', 'positive', 0.96, 0),
